44f \u043b\u0438 \u043f\u0440\u0435\u0434\u0441\u043a\u0430\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0435 \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u043e \u0441\u0443\u0440\u0440\u043e\u0433\u0430\u0442\u043d\u044b\u0445 \u043c\u043e\u0434\u0435\u043b\u0435\u0439 \u043d\u0430 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u0434\u0430\u043d\u043d\u044b\u0445 (26 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u043e\u0432) \u0441 \u0440\u043e\u0441\u0442\u043e\u043c n \u0438 \u0440\u0430\u0437\u043b\u0438\u0447\u0430\u0435\u0442\u0441\u044f \u043b\u0438 \u043f\u043e\u0432\u0435\u0434\u0435\u043d\u0438\u0435 \u043c\u0435\u0436\u0434\u0443 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u0430\u043c\u0438\u00bb (DrivAerNet++, Cd, fastback/notchback/estateback).\n\n## 2. \u0424\u0410\u041a\u0422\u042b \u041e \u0414\u0410\u041d\u041d\u042b\u0425 DrivAerNet++ (\u043f\u043e \u0432\u043d\u0435\u0448\u043d\u0435\u0439 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430\u0446\u0438\u0438 \u2014 \u0442\u0440\u0435\u0431\u0443\u044e\u0442 \u0441\u0432\u0435\u0440\u043a\u0438; \u0432 workspace \u043d\u0435 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u043c\u043e)\n\n- DrivAerNet++ (Elrefaie et al., 2024) \u2014 \u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u0438\u0435 DrivAerNet (NeurIPS 2024), \u043f\u043e\u0441\u0442\u0440\u043e\u0435\u043d\u043e \u043d\u0430 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u043c\u043e\u0434\u0435\u043b\u0438 \u043a\u0443\u0437\u043e\u0432\u0430 DrivAer (TU M\u00fcnchen).\n- **\u041e\u0431\u044a\u0451\u043c**: ~8 000 \u0443\u043d\u0438\u043a\u0430\u043b\u044c\u043d\u044b\u0445 \u0434\u0438\u0437\u0430\u0439\u043d\u043e\u0432 \u0441 CFD-\u0440\u0430\u0441\u0447\u0451\u0442\u0430\u043c\u0438 (\u0447\u0438\u0441\u043b\u043e \u043e\u0431\u0440\u0430\u0437\u0446\u043e\u0432 \u0438 \u043f\u043e\u043b\u043d\u044b\u0439 \u043e\u0431\u044a\u0451\u043c \u043d\u0443\u0436\u043d\u043e \u0441\u0432\u0435\u0440\u0438\u0442\u044c \u0441 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430\u0446\u0438\u0435\u0439: \u043f\u043e\u043b\u043d\u044b\u0439 \u0430\u0440\u0445\u0438\u0432 \u043f\u043e\u0440\u044f\u0434\u043a\u0430 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u0438\u0445 TB, \u0435\u0441\u0442\u044c \u043a\u043e\u043c\u043f\u0430\u043a\u0442\u043d\u044b\u0435 \u0432\u0435\u0440\u0441\u0438\u0438 \u00ab\u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b + Cd\u00bb).\n- **26 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u043e\u0432** \u2014 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0433\u0435\u043e\u043c\u0435\u0442\u0440\u0438\u0438/CAD (\u0433\u0430\u0431\u0430\u0440\u0438\u0442\u044b: \u0434\u043b\u0438\u043d\u0430/\u0448\u0438\u0440\u0438\u043d\u0430/\u0432\u044b\u0441\u043e\u0442\u0430, \u043a\u043e\u043b\u0451\u0441\u043d\u0430\u044f \u0431\u0430\u0437\u0430; \u0443\u0433\u043b\u044b \u043d\u0430\u043a\u043b\u043e\u043d\u0430 \u0441\u0442\u043e\u0435\u043a \u0438 \u043b\u043e\u0431\u043e\u0432\u043e\u0433\u043e \u0441\u0442\u0435\u043a\u043b\u0430, \u043a\u0440\u0438\u0432\u0438\u0437\u043d\u0430 \u043a\u0440\u044b\u0448\u0438, \u0444\u043e\u0440\u043c\u0430 \u0437\u0430\u0434\u043d\u0435\u0439 \u0447\u0430\u0441\u0442\u0438, \u0441\u043f\u043e\u0439\u043b\u0435\u0440/\u0434\u0438\u0444\u0444\u0443\u0437\u043e\u0440, \u043a\u043e\u043b\u0451\u0441\u0430 \u0438 \u0442.\u043f.). \u041f\u043e \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430\u0446\u0438\u0438 \u044d\u0442\u043e **\u0433\u0435\u043e\u043c\u0435\u0442\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b \u0434\u0438\u0437\u0430\u0439\u043d\u0430**; CFD-\u0443\u0441\u043b\u043e\u0432\u0438\u044f (\u0441\u043a\u043e\u0440\u043e\u0441\u0442\u044c \u043f\u043e\u0442\u043e\u043a\u0430, Re) \u0432 \u043d\u0430\u0431\u043e\u0440\u0435, \u043a\u0430\u043a \u043f\u0440\u0430\u0432\u0438\u043b\u043e, \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u044b \u2014 \u044d\u0442\u043e\u0442 \u043f\u0443\u043d\u043a\u0442 \u043f\u043e\u043c\u0435\u0447\u0430\u044e \u043a \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0435.\n- **\u0426\u0435\u043b\u0435\u0432\u0430\u044f \u043f\u0435\u0440\u0435\u043c\u0435\u043d\u043d\u0430\u044f** \u2014 \u0431\u0435\u0437\u0440\u0430\u0437\u043c\u0435\u0440\u043d\u044b\u0439 \u043a\u043e\u044d\u0444\u0444\u0438\u0446\u0438\u0435\u043d\u0442 \u043b\u043e\u0431\u043e\u0432\u043e\u0433\u043e \u0441\u043e\u043f\u0440\u043e\u0442\u0438\u0432\u043b\u0435\u043d\u0438\u044f `Cd`, \u043f\u043e\u043b\u0443\u0447\u0435\u043d\u043d\u044b\u0439 \u0438\u0437 CFD-\u0440\u0430\u0441\u0447\u0451\u0442\u0430; \u0432 \u043d\u0430\u0431\u043e\u0440\u0435 \u0445\u0440\u0430\u043d\u0438\u0442\u0441\u044f \u043a\u0430\u043a \u0441\u043a\u0430\u043b\u044f\u0440\u043d\u043e\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u043d\u0430 \u043e\u0431\u0440\u0430\u0437\u0435\u0446.\n- **\u0422\u0440\u0438 \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u0438 \u043a\u0443\u0437\u043e\u0432\u0430**: fastback, notchback (\u0441\u0435\u0434\u0430\u043d), estateback (\u0443\u043d\u0438\u0432\u0435\u0440\u0441\u0430\u043b); \u043a\u0430\u043a \u0438\u043c\u0435\u043d\u043d\u043e \u043e\u043d\u0438 \u0437\u0430\u043a\u043e\u0434\u0438\u0440\u043e\u0432\u0430\u043d\u044b \u0432 \u0434\u0430\u043d\u043d\u044b\u0445 \u0438 \u0435\u0441\u0442\u044c \u043b\u0438 \u0433\u043e\u0442\u043e\u0432\u043e\u0435 \u0440\u0430\u0437\u0431\u0438\u0435\u043d\u0438\u0435 train/val/test \u2014 \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u0441\u0432\u0435\u0440\u043a\u0438 \u0441 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430\u0446\u0438\u0435\u0439.\n\n## 3. \u041f\u0420\u0415\u0414\u041b\u0410\u0413\u0410\u0415\u041c\u042b\u0419 \u041f\u041e\u0414\u0425\u041e\u0414 (\u043a\u043e\u043d\u0446\u0435\u043f\u0442\u0443\u0430\u043b\u044c\u043d\u043e)\n\n**\u0414\u0430\u043d\u043d\u044b\u0435.** \u041f\u0440\u0438\u0437\u043d\u0430\u043a\u0438 \u2014 26 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u043e\u0432 \u0438\u0437 \u043d\u0430\u0431\u043e\u0440\u0430 + \u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u0430\u043b\u044c\u043d\u044b\u0439 \u043f\u0440\u0438\u0437\u043d\u0430\u043a \u00ab\u0442\u0438\u043f \u043a\u0443\u0437\u043e\u0432\u0430\u00bb (one-hot). \u0418\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u043c \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0432\u0435\u043a\u0442\u043e\u0440 (\u043d\u0435 \u0441\u0435\u0442\u043a\u0438/\u043e\u0431\u043b\u0430\u043a\u0430 \u0442\u043e\u0447\u0435\u043a) \u2014 \u044d\u0442\u043e \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442 \u0442\u0440\u0430\u043a\u0442\u043e\u0432\u043a\u0443 \u00ab\u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u0434\u0430\u043d\u043d\u044b\u0445\u00bb. \u0426\u0435\u043b\u0435\u0432\u0430\u044f \u043f\u0435\u0440\u0435\u043c\u0435\u043d\u043d\u0430\u044f \u2014 `Cd`.\n\n**\u041c\u0430\u0441\u0448\u0442\u0430\u0431\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435 \u0442\u0440\u0435\u043d\u0438\u0440\u043e\u0432\u043e\u0447\u043d\u043e\u0439 \u0432\u044b\u0431\u043e\u0440\u043a\u0438 (learning curves).**\n- \u0421\u0435\u0442\u043a\u0430 \u0440\u0430\u0437\u043c\u0435\u0440\u043e\u0432 `n` \u0432 \u043b\u043e\u0433\u0430\u0440\u0438\u0444\u043c\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0448\u043a\u0430\u043b\u0435, \u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440 `{50, 100, 200, 400, 800, 1600, 3200, ...}` \u0434\u043e ~80% \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e\u0433\u043e \u043e\u0431\u044a\u0451\u043c\u0430 (\u0430\u0434\u0430\u043f\u0442\u0438\u0432\u043d\u043e \u043a \u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u043c\u0443 `N`).\n- \u0414\u043b\u044f \u043a\u0430\u0436\u0434\u043e\u0433\u043e `n` \u2014 `R` \u043f\u043e\u0432\u0442\u043e\u0440\u0435\u043d\u0438\u0439 **\u0441\u0442\u0440\u0430\u0442\u0438\u0444\u0438\u0446\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0433\u043e** \u0441\u0443\u0431\u0441\u0435\u043c\u043f\u043b\u0438\u043d\u0433\u0430 \u043f\u043e \u0442\u0438\u043f\u0443 \u043a\u0443\u0437\u043e\u0432\u0430 (\u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0435 \u043f\u043e\u0434\u0432\u044b\u0431\u043e\u0440\u043a\u0438 \u0434\u043b\u044f \u0432\u0441\u0435\u0445 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440 \u2014 \u043f\u0430\u0440\u043d\u044b\u0439 \u0434\u0438\u0437\u0430\u0439\u043d, \u0438\u0441\u043a\u043b\u044e\u0447\u0430\u0435\u0442 \u0448\u0443\u043c \u0432\u044b\u0431\u043e\u0440\u043a\u0438 \u043c\u0435\u0436\u0434\u0443 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u0430\u043c\u0438). `R` \u2248 10\u201330, \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 seed'\u044b.\n- \u041e\u0446\u0435\u043d\u043a\u0430 \u043d\u0430 **\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u043c \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u043c \u0442\u0435\u0441\u0442\u0435** (\u0435\u0434\u0438\u043d\u044b\u0439 \u0441\u0442\u0440\u0430\u0442\u0438\u0444\u0438\u0446\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 hold-out ~20%, \u043d\u0438\u043a\u043e\u0433\u0434\u0430 \u043d\u0435 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044f \u043f\u0440\u0438 \u043f\u043e\u0441\u0442\u0440\u043e\u0435\u043d\u0438\u0438 \u043a\u0440\u0438\u0432\u044b\u0445 \u0438 \u043f\u0440\u0438 \u043d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0435), \u0447\u0442\u043e\u0431\u044b \u043a\u0440\u0438\u0432\u044b\u0435 \u0440\u0430\u0437\u043d\u044b\u0445 n/\u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440 \u0431\u044b\u043b\u0438 \u0441\u043e\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u043c\u044b.\n\n**\u0410\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u044b** (\u043f\u043e\u043a\u0440\u044b\u0432\u0430\u044e\u0442 \u043a\u043b\u0430\u0441\u0441\u044b \u0433\u0438\u043f\u043e\u0442\u0435\u0437): \u043b\u0438\u043d\u0435\u0439\u043d\u0430\u044f \u0440\u0435\u0433\u0443\u043b\u044f\u0440\u0438\u0437\u043e\u0432\u0430\u043d\u043d\u0430\u044f (ridge/Lasso) \u2014 \u043f\u043b\u0430\u0442\u043e \u043f\u0440\u0438 \u043c\u0430\u043b\u044b\u0445 n; \u0441\u043b\u0443\u0447\u0430\u0439\u043d\u044b\u0439 \u043b\u0435\u0441; \u0433\u0440\u0430\u0434\u0438\u0435\u043d\u0442\u043d\u044b\u0439 \u0431\u0443\u0441\u0442\u0438\u043d\u0433 (LightGBM/XGBoost, \u043f\u0440\u0438 \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e\u0441\u0442\u0438 \u2014 HistGradientBoosting \u0438\u0437 sklearn); \u0433\u0430\u0443\u0441\u0441\u043e\u0432\u0441\u043a\u0438\u0439 \u043f\u0440\u043e\u0446\u0435\u0441\u0441 (GP, \u044f\u0434\u0440\u043e ARD/RBF; \u0438\u0437-\u0437\u0430 O(n\u00b3) \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u0434\u043e \u0443\u043c\u0435\u0440\u0435\u043d\u043d\u044b\u0445 n \u043b\u0438\u0431\u043e \u0440\u0430\u0437\u0440\u0435\u0436\u0435\u043d\u043d\u043e\u0435 \u043f\u0440\u0438\u0431\u043b\u0438\u0436\u0435\u043d\u0438\u0435); MLP (\u043d\u0435\u0431\u043e\u043b\u044c\u0448\u043e\u0439, 2\u20133 \u0441\u043a\u0440\u044b\u0442\u044b\u0445 \u0441\u043b\u043e\u044f). \u041f\u0440\u0438 \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e\u0441\u0442\u0438 \u0431\u0438\u0431\u043b\u0438\u043e\u0442\u0435\u043a \u0432 \u0446\u0435\u043b\u0435\u0432\u043e\u0439 \u0441\u0440\u0435\u0434\u0435 \u2014 \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u044c (numpy/pandas/sklearn/scipy) \u0432 \u0444\u0438\u043d\u0430\u043b\u044c\u043d\u043e\u043c \u0434\u0438\u0437\u0430\u0439\u043d\u0435.\n\n**\u0420\u0430\u0437\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u0438 \u0432\u0430\u043b\u0438\u0434\u0430\u0446\u0438\u044f.** \u0413\u0438\u043f\u0435\u0440\u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u044e\u0442\u0441\u044f **\u043e\u0434\u0438\u043d \u0440\u0430\u0437** \u043d\u0430 \u0440\u0435\u043f\u0440\u0435\u0437\u0435\u043d\u0442\u0430\u0442\u0438\u0432\u043d\u043e\u043c \u043f\u043e\u0434\u043d\u0430\u0431\u043e\u0440\u0435 (\u0432\u043d\u0435 \u0442\u0435\u0441\u0442\u0430) \u0438 \u043d\u0435 \u043f\u0435\u0440\u0435\u043d\u0430\u0441\u0442\u0440\u0430\u0438\u0432\u0430\u044e\u0442\u0441\u044f \u043f\u043e\u0434 \u043a\u0430\u0436\u0434\u044b\u0439 `n` \u2014 \u0438\u043d\u0430\u0447\u0435 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043a\u0440\u0438\u0432\u044b\u0445 \u0438\u0441\u043a\u0430\u0436\u0430\u0435\u0442\u0441\u044f \u043f\u0435\u0440\u0435\u043e\u0431\u0443\u0447\u0435\u043d\u0438\u0435\u043c \u043f\u043e\u0434 \u0432\u044b\u0431\u043e\u0440\u043a\u0443. \u0412\u043d\u0443\u0442\u0440\u0438 \u0442\u0440\u0435\u043d\u0438\u0440\u043e\u0432\u043e\u0447\u043d\u043e\u0439 \u0447\u0430\u0441\u0442\u0438 \u2014 \u0441\u0442\u0440\u0430\u0442\u0438\u0444\u0438\u0446\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u0430\u044f K-fold \u043a\u0440\u043e\u0441\u0441-\u0432\u0430\u043b\u0438\u0434\u0430\u0446\u0438\u044f \u0434\u043b\u044f \u043a\u0430\u043b\u0438\u0431\u0440\u043e\u0432\u043a\u0438, \u0442\u0435\u0441\u0442 \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u0432 \u043a\u043e\u043d\u0446\u0435.\n\n**\u041c\u0435\u0442\u0440\u0438\u043a\u0438.** `RMSE`, `MAE` \u043d\u0430 `Cd` + \u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0432\u0435\u0440\u0441\u0438\u0438 (`RMSE/MAE`, \u043d\u043e\u0440\u043c\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u043d\u0430 std \u0442\u0435\u0441\u0442\u043e\u0432\u043e\u0433\u043e `Cd`), `R\u00b2`. \u0422\u043e\u0447\u043a\u0438 \u043a\u0440\u0438\u0432\u043e\u0439 \u2014 \u0441\u0440\u0435\u0434\u043d\u0435\u0435 \u043f\u043e R \u043f\u043e\u0432\u0442\u043e\u0440\u0430\u043c \u0441 SE/95% \u0414\u0418.\n\n**\u0421\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u043e\u0431\u043e\u0441\u043d\u043e\u0432\u0430\u043d\u0438\u0435 \u00ab\u0443\u043b\u0443\u0447\u0448\u0435\u043d\u0438\u044f \u0441 \u0440\u043e\u0441\u0442\u043e\u043c n\u00bb.**\n- \u0414\u043b\u044f \u043a\u0430\u0436\u0434\u043e\u0439 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u044b \u2014 \u043e\u0446\u0435\u043d\u043a\u0430 \u043d\u0430\u043a\u043b\u043e\u043d\u0430 \u043a\u0440\u0438\u0432\u043e\u0439 `log(\u043e\u0448\u0438\u0431\u043a\u0430) ~ log(n)` (\u0440\u0435\u0433\u0440\u0435\u0441\u0441\u0438\u044f \u043f\u043e \u0442\u043e\u0447\u043a\u0430\u043c \u0441\u0440\u0435\u0434\u043d\u0438\u0445, \u041c\u041d\u041a \u0441 \u0443\u0447\u0451\u0442\u043e\u043c \u0414\u0418 \u0442\u043e\u0447\u0435\u043a); \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u043e\u0434\u043d\u043e\u0441\u0442\u043e\u0440\u043e\u043d\u043d\u0435\u0439 \u0433\u0438\u043f\u043e\u0442\u0435\u0437\u044b \u043d\u0430\u043a\u043b\u043e\u043d < 0 (\u0443\u043b\u0443\u0447\u0448\u0435\u043d\u0438\u0435) \u0438 \u0442\u0435\u0441\u0442 \u0437\u043d\u0430\u0447\u0438\u043c\u043e\u0441\u0442\u0438 \u043e\u0442\u043b\u0438\u0447\u0438\u044f \u043e\u0442 0 (t-\u0442\u0435\u0441\u0442 \u043f\u043e \u043d\u0430\u043a\u043b\u043e\u043d\u0443, \u0434\u043e\u043f\u043e\u043b\u043d\u0435\u043d\u043d\u043e \u0431\u0443\u0442\u0441\u0442\u0440\u0430\u043f\u043e\u043c \u043f\u043e \u043f\u043e\u0434\u0432\u044b\u0431\u043e\u0440\u043a\u0430\u043c).\n- \u0421\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440: \u043f\u0430\u0440\u043d\u044b\u0439 \u0431\u0443\u0442\u0441\u0442\u0440\u0430\u043f \u0440\u0430\u0437\u043d\u043e\u0441\u0442\u0438 \u043e\u0448\u0438\u0431\u043e\u043a \u043f\u0440\u0438 \u0441\u043e\u0432\u043f\u0430\u0434\u0430\u044e\u0449\u0438\u0445 `n` (+ \u043f\u043e\u043f\u0440\u0430\u0432\u043a\u0430 \u043d\u0430 \u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0441\u0442\u044c, e.g. Bonferroni; \u043f\u0440\u0438 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u0438\u0445 arch \u2014 \u0442\u0435\u0441\u0442 \u0424\u0440\u0438\u0434\u043c\u0430\u043d\u0430 + \u043f\u043e\u0441\u0442-\u0445\u043e\u043a Nemenyi \u043b\u0438\u0431\u043e \u043f\u0430\u0440\u043d\u044b\u0435 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f \u0441 \u043a\u043e\u0440\u0440\u0435\u043a\u0446\u0438\u0435\u0439).\n- \u00ab\u0420\u0430\u0437\u043b\u0438\u0447\u0430\u0435\u0442\u0441\u044f \u043b\u0438 \u043f\u043e\u0432\u0435\u0434\u0435\u043d\u0438\u0435\u00bb = \u043d\u0430\u043b\u0438\u0447\u0438\u0435 **\u0432\u0437\u0430\u0438\u043c\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f arch \u00d7 n**: \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043d\u0430\u043a\u043b\u043e\u043d\u043e\u0432 \u043a\u0440\u0438\u0432\u044b\u0445 \u043c\u0435\u0436\u0434\u0443 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u0430\u043c\u0438 (\u0431\u0443\u0442\u0441\u0442\u0440\u0430\u043f/\u043f\u0435\u0440\u043c\u0443\u0442\u0430\u0446\u0438\u043e\u043d\u043d\u044b\u0439 \u0442\u0435\u0441\u0442 \u0440\u0430\u0437\u043d\u043e\u0441\u0442\u0438 \u043d\u0430\u043a\u043b\u043e\u043d\u043e\u0432, \u0438\u043b\u0438 \u0441\u043c\u0435\u0448\u0430\u043d\u043d\u0430\u044f \u043c\u043e\u0434\u0435\u043b\u044c `log(error) ~ log(n) * arch` \u0441 \u0444\u0438\u043a\u0441. \u044d\u0444\u0444\u0435\u043a\u0442\u0430\u043c\u0438). \u0414\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u00ab\u043d\u0430\u0441\u044b\u0449\u0435\u043d\u0438\u044f\u00bb (\u0438\u0437\u043b\u043e\u043c/\u043f\u043b\u0430\u0442\u043e) \u2014 \u043a\u0432\u0430\u0434\u0440\u0430\u0442\u0438\u0447\u043d\u044b\u0439 \u0447\u043b\u0435\u043d \u0438\u043b\u0438 \u043a\u0443\u0441\u043e\u0447\u043d\u0430\u044f \u0440\u0435\u0433\u0440\u0435\u0441\u0441\u0438\u044f.\n\n**\u041a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0430 \u0434\u0438\u0437\u0430\u0439\u043d\u0430.** \u041f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u044f \u0443\u0442\u0435\u0447\u043a\u0438 (\u0442\u0435\u0441\u0442 \u043d\u0438\u043a\u043e\u0433\u0434\u0430 \u043d\u0435 \u0443\u0447\u0430\u0441\u0442\u0432\u0443\u0435\u0442 \u0432 \u043d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0435); \u0438\u0434\u0435\u043d\u0442\u0438\u0447\u043d\u043e\u0441\u0442\u044c \u043f\u043e\u0434\u0432\u044b\u0431\u043e\u0440\u043e\u043a \u043c\u0435\u0436\u0434\u0443 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u0430\u043c\u0438; \u0441\u0442\u0440\u0430\u0442\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f; \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u0434\u0443\u0431\u043b\u0438\u043a\u0430\u0442\u043e\u0432/\u043f\u043e\u0447\u0442\u0438-\u0434\u0443\u0431\u043b\u0438\u043a\u0430\u0442\u043e\u0432 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u043e\u0432; \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u043a\u043e\u0440\u0440\u0435\u043b\u044f\u0446\u0438\u0439 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u043e\u0432 (\u043c\u0430\u0442\u0440\u0438\u0446\u0430 \u043a\u043e\u0440\u0440\u0435\u043b\u044f\u0446\u0438\u0439, \u043c\u0443\u043b\u044c\u0442\u0438\u043a\u043e\u043b\u043b\u0438\u043d\u0435\u0430\u0440\u043d\u043e\u0441\u0442\u044c) \u043a\u0430\u043a \u043a\u043e\u043d\u0442\u0435\u043a\u0441\u0442 \u0434\u043b\u044f \u0438\u043d\u0442\u0435\u0440\u043f\u0440\u0435\u0442\u0430\u0446\u0438\u0438.\n\n**\u041e\u0446\u0435\u043d\u043a\u0430 \u0432\u044b\u043f\u043e\u043b\u043d\u0438\u043c\u043e\u0441\u0442\u0438.** \u041f\u0440\u0438 N\u22488000, 26 \u043f\u0440\u0438\u0437\u043d\u0430\u043a\u043e\u0432, 224 CPU: ridge/RF/boosting/MLP \u2014 \u0434\u0451\u0448\u0435\u0432\u044b (\u043c\u0438\u043d\u0443\u0442\u044b\u2013\u0447\u0430\u0441\u044b \u0441\u0443\u043c\u043c\u0430\u0440\u043d\u043e); GP \u0434\u043e\u0440\u043e\u0433\u043e\u0439 \u043f\u0440\u0438 \u0431\u043e\u043b\u044c\u0448\u0438\u0445 n \u2014 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0438\u0442\u044c \u0434\u0438\u0430\u043f\u0430\u0437\u043e\u043d n \u0434\u043b\u044f GP \u043b\u0438\u0431\u043e \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u044c \u0440\u0430\u0437\u0440\u0435\u0436\u0435\u043d\u043d\u043e\u0435 \u043f\u0440\u0438\u0431\u043b\u0438\u0436\u0435\u043d\u0438\u0435. \u0412\u0435\u0441\u044c \u043f\u0440\u043e\u0433\u043e\u043d \u0432\u044b\u043f\u043e\u043b\u043d\u0438\u043c \u043d\u0430 \u043e\u0434\u043d\u043e\u043c CPU-\u0441\u0435\u0440\u0432\u0435\u0440\u0435; ML-\u0441\u0442\u0435\u043a \u043d\u0443\u0436\u043d\u043e \u0434\u043e\u0443\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u044c (\u0432\u043d\u0435 \u0441\u0435\u0442\u0438 \u044d\u0442\u043e \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e\u0435 \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435 \u0434\u043b\u044f \u043f\u0440\u043e\u0433\u043e\u043d\u0430 \u0444\u0438\u043d\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u0430 \u2014 \u0437\u0434\u0435\u0441\u044c \u0434\u0438\u0437\u0430\u0439\u043d, \u0430 \u043d\u0435 \u0437\u0430\u043f\u0443\u0441\u043a).\n\n## 4. \u041a\u041b\u042e\u0427\u0415\u0412\u042b\u0415 \u0414\u041e\u041f\u0423\u0429\u0415\u041d\u0418\u042f\n1. \u00ab\u041f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u0434\u0430\u043d\u043d\u044b\u0435\u00bb = 26-\u043c\u0435\u0440\u043d\u044b\u0439 \u0432\u0435\u043a\u0442\u043e\u0440 \u043d\u0430 \u043e\u0431\u0440\u0430\u0437\u0435\u0446 (+ \u0442\u0438\u043f \u043a\u0443\u0437\u043e\u0432\u0430); \u0441\u0435\u0442\u043a\u0438/\u043e\u0431\u043b\u0430\u043a\u0430 \u043d\u0435 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u044e\u0442\u0441\u044f.\n2. \u0424\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 `N`, \u0447\u0438\u0441\u043b\u043e \u0443\u043d\u0438\u043a\u0430\u043b\u044c\u043d\u044b\u0445 \u0434\u0438\u0437\u0430\u0439\u043d\u043e\u0432, \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u043f\u043e \u0442\u0438\u043f\u0430\u043c \u043a\u0443\u0437\u043e\u0432\u0430 \u0438 \u0438\u0445 \u0434\u043e\u043b\u044f \u2014 \u043d\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u043d\u044b \u0431\u0435\u0437 \u0434\u043e\u0441\u0442\u0443\u043f\u0430 \u043a \u043d\u0430\u0431\u043e\u0440\u0443; \u0434\u0438\u0437\u0430\u0439\u043d \u0430\u0434\u0430\u043f\u0442\u0438\u0432\u0435\u043d (\u0441\u0435\u0442\u043a\u0430 n \u0441\u0442\u0440\u043e\u0438\u0442\u0441\u044f \u043e\u0442 \u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e N; \u0441\u0442\u0440\u0430\u0442\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f \u043f\u043e \u0442\u0438\u043f\u0430\u043c).\n3. `Cd` \u2014 \u044d\u0442\u043e \u0441\u043a\u0430\u043b\u044f\u0440\u043d\u0430\u044f \u043c\u0435\u0442\u043a\u0430 \u0438\u0437 \u043d\u0430\u0431\u043e\u0440\u0430; \u0442\u043e\u0447\u043d\u043e\u0441\u0442\u044c/\u0448\u0443\u043c \u043c\u0435\u0442\u043e\u043a \u043f\u0440\u0438\u043d\u044f\u0442\u044b \u043a\u0430\u043a \u0435\u0441\u0442\u044c (\u043d\u0435 \u043f\u0435\u0440\u0435\u0441\u0447\u0438\u0442\u044b\u0432\u0430\u044e\u0442\u0441\u044f CFD).\n4. \u0421\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u043d\u044b\u0435 \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f \u0434\u0438\u0437\u0430\u0439\u043d\u0430: \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0433\u0438\u043f\u0435\u0440\u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b, \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u044b\u0439 \u0442\u0435\u0441\u0442, \u043f\u0430\u0440\u043d\u044b\u0435 \u043f\u043e\u0434\u0432\u044b\u0431\u043e\u0440\u043a\u0438.\n\n## 5. \u041d\u0415\u041e\u041f\u0420\u0415\u0414\u0415\u041b\u0401\u041d\u041d\u041e\u0421\u0422\u0418 / \u0432\u043e\u043f\u0440\u043e\u0441\u044b \u043a \u0441\u0432\u0435\u0440\u043a\u0435 (\u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0435 \u043f\u043e\u0434\u043b\u0435\u0436\u0430\u0442 \u043f\u043e \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430\u0446\u0438\u0438 \u043d\u0430\u0431\u043e\u0440\u0430 \u0432 \u043c\u043e\u043c\u0435\u043d\u0442 \u0438\u0441\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u044f)\n- \u0422\u043e\u0447\u043d\u044b\u0439 \u043e\u0431\u044a\u0451\u043c \u0432\u044b\u0431\u043e\u0440\u043a\u0438 \u0438 \u043f\u043e\u043b\u043d\u044b\u0439 \u0441\u043e\u0441\u0442\u0430\u0432 26 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u043e\u0432 (\u0435\u0441\u0442\u044c \u043b\u0438 \u0441\u0440\u0435\u0434\u0438 \u043d\u0438\u0445 \u043d\u0435-\u0433\u0435\u043e\u043c\u0435\u0442\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0435/\u0443\u0441\u043b\u043e\u0432\u0438\u044f).\n- \u041a\u043e\u0434\u0438\u0440\u043e\u0432\u043a\u0430 \u0442\u0438\u043f\u0430 \u043a\u0443\u0437\u043e\u0432\u0430 \u0438 \u043d\u0430\u043b\u0438\u0447\u0438\u0435 \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u0440\u0430\u0437\u0431\u0438\u0435\u043d\u0438\u044f train/val/test.\n- \u041a\u043e\u0440\u0440\u0435\u043b\u044f\u0446\u0438\u043e\u043d\u043d\u0430\u044f \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u043e\u0432 \u0438 \u043d\u0430\u043b\u0438\u0447\u0438\u0435 \u043f\u043e\u0447\u0442\u0438-\u0434\u0443\u0431\u043b\u0438\u043a\u0430\u0442\u043e\u0432 (\u0432\u043b\u0438\u044f\u0435\u0442 \u043d\u0430 \u044d\u0444\u0444\u0435\u043a\u0442\u0438\u0432\u043d\u044b\u0439 (\u043d\u0435 \u043d\u043e\u043c\u0438\u043d\u0430\u043b\u044c\u043d\u044b\u0439) \u0440\u0430\u0437\u043c\u0435\u0440 \u0432\u044b\u0431\u043e\u0440\u043a\u0438 \u2014 \u0440\u0438\u0441\u043a \u00ab\u043a\u0430\u0436\u0443\u0449\u0435\u0433\u043e\u0441\u044f\u00bb \u043d\u0430\u0441\u044b\u0449\u0435\u043d\u0438\u044f \u043a\u0440\u0438\u0432\u043e\u0439).\n\n\u0412\u043e\u043f\u0440\u043e\u0441\u044b \u043a \u0438\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044e (\u0443\u0442\u043e\u0447\u043d\u0438\u0442\u044c \u0434\u043e \u0444\u0438\u043d\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u0434\u0438\u0437\u0430\u0439\u043d\u0430): (1) \u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c \u043b\u0438 GP \u0432 \u0441\u043f\u0438\u0441\u043a\u0435 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440 (\u0434\u043e\u0440\u043e\u0433\u043e \u043f\u0440\u0438 \u0431\u043e\u043b\u044c\u0448\u0438\u0445 n) \u0438\u043b\u0438 \u0437\u0430\u043c\u0435\u043d\u0438\u0442\u044c \u043d\u0430 \u0431\u043e\u043b\u0435\u0435 \u0434\u0435\u0448\u0451\u0432\u044b\u0435; (2) \u043f\u0440\u0438\u0435\u043c\u043b\u0435\u043c\u043e \u043b\u0438 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0433\u0438\u043f\u0435\u0440\u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b \u043e\u0434\u0438\u043d \u0440\u0430\u0437, \u043b\u0438\u0431\u043e \u0442\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044f \u043f\u0435\u0440\u0435\u043d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0430 \u0432\u043d\u0443\u0442\u0440\u0438 \u043a\u0430\u0436\u0434\u043e\u0433\u043e n; (3) \u043a\u0430\u043a\u043e\u0439 \u043c\u0438\u043d\u0438\u043c\u0430\u043b\u044c\u043d\u044b\u0439 \u043d\u0430\u0431\u043e\u0440 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440 \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u0435\u043d (\u043c\u0438\u043d\u0438\u043c\u0430\u043b\u044c\u043